  if (pathName.endsWith(".guides.po")) return false;
  if (pathName.endsWith(".api.po")) return fixtures.apiPo !== null;
  const cacheStates = [
    [".guides.json", fixtures.guidesCache],
    [".api.json", fixtures.apiCache],
    [".home.json", fixtures.homeCache],
